/// <summary>
/// Data contract class for service <c>METSalesOrderReturnCreditRegistrationContract</c>
/// </summary>
[DataContractAttribute]
public class METSalesOrderReturnCreditRegistrationContract
{
    SalesReturnItemNum          rmaNumber;
    LineNum                     lineNumber;
    DataAreaId                  dataAreaId;

}

Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Parameter method for RMA number
/// </summary>
/// <param name = "_rmaNumber">RMA reference</param>
/// <returns>RMANumber</returns>
[DataMemberAttribute('RMANumber')]
public SalesReturnItemNum parmRMANumber(SalesReturnItemNum _rmaNumber = rmaNumber )
{
    rmaNumber  = _rmaNumber;
    return rmaNumber ;
}

/// <summary>
/// Parameter method for line number
/// </summary>
/// <param name = "_lineNumber">Line number</param>
/// <returns>Line number</returns>
[DataMemberAttribute('LineNumber')]
public LineNum parmLineNumber(LineNum _lineNumber = lineNumber )
{
    lineNumber  = _lineNumber;
    return lineNumber ;
}

/// <summary>
/// Instantiate new object
/// </summary>
/// <returns>The new object</returns>
public static METSalesOrderReturnCreditRegistrationContract construct()
{
    return new METSalesOrderReturnCreditRegistrationContract();
}
